    "skill": "Words in Context",
    "difficulty": "Easy",
    "difficultyStatus": "provisional",
    "passage": "Among humans, even thinking about yawning can trigger the reflex, leading some to suspect that catching a yawn is linked to our ability to empathize with other humans. For instance, contagious yawning activates the same part of the brain that <u>governs</u> empathy and social know-how. And some studies have shown that humans with more fine-tuned social skills are more likely to catch a yawn.",
    "question": "As used in the text, what does \"governs\" mean?",
    "options": [
      "A. elects",
      "B. requires",
      "C. controls",
      "D. suppresses"
    ],
    "answer": "C",
    "explanation": "The passage is discussing the part of the brain that ___ contagious yawning along with empathy and social-know how. The body's abilities are controlled by the brain, so in this context, governs must mean\" controls.\" (C) is thus correct. \"Elect\" is a word that is often associated with governing, but in the context of the brain, it does not make sense. That eliminates (A). \"Requires\" does not mean \"controls,\" so (B) can be eliminated as well. \"Suppresses\" (prevents) is exactly the opposite of the required meaning. The passage states that catching a yawn is linked to our ability to empathize, so all those skills must be activated together. That eliminates (D).",
    "strategy": "Two-Filter Method",
