    "id": "fda4a6c0",
    "skill": "Words in Context",
    "difficulty": "Easy",
    "difficultyStatus": "provisional",
    "passage": "The following text is from Emily Brontë's 1847 novel Wuthering Heights. The narrator is bringing a boy named Linton to his father. The boy was fully occupied with his own cogitations for the remainder of the ride, till we halted before the farmhouse garden-gate. I watched to <u>catch</u> his impressions in his countenance. He surveyed the carved front and low-browed lattices, the straggling gooseberry-bushes and crooked firs, with solemn intentness, and then shook his head: his private feelings entirely disapproved of the exterior of his new abode.",
    "question": "As used in the text, what does \"catch\" mean?",
    "options": [
      "A. acquire",
      "B. gather",
      "C. attain",
      "D. observe"
    ],
    "answer": "D",
    "explanation": "The beginning of the passage indicates that the boy was fully occupied with his own cogitations (that is, lost in his thoughts) during the ride, and the last sentence indicates that the narrator carefully watched the boy as he inspected his new surroundings. Given that context, catch must logically mean something like \"see\" (countenance means \"face\"). The best fit for this definition is \"observe\" - the sentence is essentially saying that the narrator wanted to see how the boy would react. (A) does not fit because it does not make sense to say that someone \"acquired\" another person's impressions. (B) does not fit because it is illogical to say that a person \"gathered\" ( collected) impressions in someone's face. (C) likewise does not make any sense because a person must\" attain\" (achieve) their own facial reaction. (D) is thus correct.",
    "strategy": "Two-Filter Method",
    "source": {
      "book": "The Critical Reader, Fifth Edition",
      "questionPage": 49,
      "keyPage": 59,
      "ref": "critical_reader_p049_q01"
    },
