    "skill": "Words in Context",
    "difficulty": "Easy",
    "difficultyStatus": "provisional",
    "passage": "As a painter, Georgia O'Keeffe is so closely <u>tied to</u> the American Southwest that it is hard to imagine her anywhere but the desert. In 1939, however, she accepted a commission to travel to Hawaii and paint scenes for a campaign promoting pineapple juice. Although serious artists did not normally take on commercial work, O'Keeffe was won over by images of palm trees and sandy white beaches.",
    "question": "As used in the text, what does \"tied to\" mean?",
    "options": [
      "A. held down",
      "B. engaged with",
      "C. fastened to",
      "D. associated with"
    ],
    "answer": "D",
    "explanation": "The passage indicates that it is hard to imagine [O'Keeffe] anywhere but the desert, so logically, she must be strongly \"identified with\" or \"associated with\" the American Southwest. (D) is a direct match for this meaning, so it is correct. \"Held down\" and \"fastened to\" do not make any sense in context, so (A) and (C) can be eliminated. O'Keeffe may have been\" engaged with\" the American Southwest in her paintings; however, this phrase does not fit the definition indicated by the passage.",
