    "ruleType": "Function",
    "difficulty": "Hard",
    "difficultyStatus": "provisional",
    "passage": "Far below the mid-ocean ridge volcanoes and their countless layers of crust-forming lava is the mantle, a 3,200-kilometer-thick layer of scorching hot rock that forms the earth's midsection and surrounds its metallic core. <u>At the planet's cool surface, upthrusted mantle rocks are dark green, but if you could see them in their rightful home, they would be glowing red- or even white-hot.</u> The top of the mantle is about 1,300 degrees Celsius, and it gets about one degree hotter with each kilometer of depth. The weight of overlying rock means the pressure also increases with depth about 1,000 atmospheres for every three kilometers.",
    "question": "Which choice best states the function of the underlined sentence within the text as a whole?",
    "options": [
      "A. To convey the intense pressure that pervades the mantle",
      "B. To suggest that scientific understanding of mantle rocks is limited",
      "C. To describe a difference between mantle rocks and other types of rock",
      "D. To emphasize a difference between mantle rocks in different locations"
    ],
    "answer": "D",
    "explanation": "This is a good example of a function question whose answer depends only on the underlined sentence itself rather than on the information before or after it. The key word but occurs halfway through the sentence and indicates that its purpose is to describe a contrast: the first half of the sentence describes mantle rocks at the surface (green), whereas the second half describes them deep beneath the earth (very hot). In other words, it\" emphasizes a difference between mantle rocks in two locations,\" making the answer (D). {A) is incorrect because the underlined sentence focuses on heat, not pressure. (B) is entirely off-topic, and (C) does not fit because the underlined sentence describes mantle rocks only.",
