    "id": "a283f47e",
    "skill": "Text Structure and Purpose",
    "ruleType": "Function",
    "difficulty": "Hard",
    "difficultyStatus": "provisional",
    "passage": "In order to better understand people's receptiveness to opposing viewpoints, public policy scholars Julia Minson of Harvard University and Frances Chen of the University of British Columbia reviewed dozens of studies spanning 1984 to 2021. Among their findings was the fact that people who feel strongly about an issue can be receptive to others' views without altering their own opinions. <u>As the researchers point out, two thoughtful people might examine each other's ideas seriously and, recognizing that it is possible for reasonable people to hold either perspective, respectfully agree to disagree.</u>",
    "question": "Which choice best states the function of the underlined sentence within the text as a whole?",
    "options": [
      "A. It highlights a potential outcome of a strong disagreement.",
      "B. It describes a process by which people's opinions can evolve.",
      "C. It emphasizes the importance of considering multiple perspectives.",
      "D. It discusses a strategy that permits opposing parties to reconcile their differences."
    ],
    "answer": "A",
    "explanation": "The underlined sentence begins with the phrase As the researchers point out, indicating that the information that follows will focus on an implication or conclusion of the research described in the previous sentences. The previous sentence discusses the finding that two people who feel strongly about an issue can be receptive to others' views without altering their own opinions, and the underlined sentence expands on that idea. (A) is correct because disagreeing respectfully is something that people with strongly opposing opinions might choose to do at the end of an argument- that is \"a potential outcome.\" (B) and (D) are both contradicted by the passage. The focus here is on people whose views do not evolve, or who do not reconcile (bring together) their differences. Although the passage does discuss how individuals with different perspectives might interact, (C) is incorrect because the sentence in question does not mention \"the importance of multiple perspectives.\"",
    "strategy": "Function Map",
    "source": {
      "book": "The Critical Reader, Fifth Edition",
      "questionPage": 114,
      "keyPage": 119,
      "ref": "critical_reader_p114_q01"
    },
    "origin": "book-ugsg",
