    "id": "9d6b0c8c",
    "skill": "Text Structure and Purpose",
    "ruleType": "Purpose",
    "difficulty": "Hard",
    "difficultyStatus": "provisional",
    "passage": "One of the most persistent and problematic biases in science involves motivated reasoning—that is, the tendency to interpret observations to fit preconceived notions. According to Professor Brian Nosek, a specialist in human biases and co-founder of the Center for Open Science at the University of Virginia, psychologists have demonstrated that “most of our reasoning is in fact rationalization.” In other words, people begin by making decisions about what to think or do, and their “explanation” later serves as a means to justify what they believed or how they intended to act in the first place.",
    "question": "Which choice best states the primary purpose of the text?",
    "options": [
      "A. To describe a phenomenon detrimental to the reliability of scientific findings",
      "B. To suggest that true objectivity in science cannot be attained",
      "C. To emphasize the inaccuracy of many scientific conclusions",
      "D. To call attention to the dangers of motivated reasoning"
    ],
    "answer": "A",
    "explanation": "Although the question asks about the passage a whole, you can get a sense of the answer by using only the first sentence. (In a passage this short, the primary purpose is essentially required to be presented very close to the beginning.) The phrase One of the most persistent and problematic biases in science indicates that the passage will present and discuss this problem. The language is moderate and neutral, suggesting that the correct answer will be so as well. (A) is consistent with the stated purpose and does not go outside the bounds of the passage, so it is correct. (B) is too extreme - the passage only states that motivated reasoning is a problem, not that \"true objectivity cannot be attained.\" Be careful with (C): the passage only indicates that scientists have a tendency to interpret observations to fit preconceived notions- it does not go so far as to emphasize that \"many scientific conclusions\" are actually wrong, only that they have been arrived at in a way that is not fully objective. (D) is too extreme and too negative, and the passage never explicitly discusses any dangers.",
    "strategy": "Function Map",
    "source": {
      "book": "The Critical Reader, Fifth Edition",
      "questionPage": 115,
      "keyPage": 120,
      "ref": "critical_reader_p115_q02"
    },
    "origin": "book-ugsg",
    "psatDifficulty": "Hard",
    "altIds": [],
    "psatDifficultyFrom": "mapped-from-sat",
    "retiredOn": "2026-10-08",
    "retiredFrom": "data-craft-structure-ext.js"
