    "skill": "Cross-Text Connections",
    "difficulty": "Hard",
    "difficultyStatus": "provisional",
    "passage": "Text 1 On May 21, 2019, midsize black holes were detected for the first time when the U.S.-based Laser Interferometer Gravitational-Wave Observatory (LIGO) and its European counterpart Virgo captured a tremor from a pair of black holes merging deep in space. Priyamvada Natarajan, an astrophysicist who has long worked on black-hole growth models, believes that black holes this size are born in nuclear star clusters, dense collections of stars found near galactic centers. These holes sweep through the cluster, adding gas and dust, until they settle at a single location and cease to expand. Text 2 Imre Bartos and other researchers working on “hierarchical merger” models, in which black holes grow by eating one another, focus on one major data point in the LIGO/Virgo findings. The angular momentum, or “spin,” of a black hole ranges from 0 to 1. When two black holes of similar size combine, the resulting black hole usually has a spin of around 0.7. Significantly, the two black holes involved in the merger recorded by LIGO and Virgo had 0.69 and 0.73 respectively, suggesting that they both might have formed in previous mergers.",
