    "skill": "Inferences",
    "difficulty": "Hard",
    "difficultyStatus": "provisional",
    "passage": "Although it is widely assumed that cognitive bias clouds our assessment of the people around us, their research and that of others, a group of researchers at the Santa Fe Institute has found that people's estimations of what their friends and family believe are often largely correct. That's because as highly social creatures, we have become very good at sizing up those around us—what researchers call “social sensing.” It is therefore possible ______",
