    "skill": "Inferences",
    "difficulty": "Hard",
    "difficultyStatus": "provisional",
    "passage": "One of the most startling discoveries of the early 21st century was that Indo-European languages seem not to have been spread by Anatolian farmers living in what is now Turkey, as was commonly thought, but rather by a people called the Yamnaya, horse-herding nomads who lived on the Eurasian steppes more than 5,000 years ago. A host of linguistic evidence suggesting this possibility was first compiled persuasively by archaeologist David Anthony in 2007; DNA evidence later proved he was on target, showing that ______",
