    "skill": "Inferences",
    "difficulty": "Hard",
    "difficultyStatus": "provisional",
    "passage": "When Isaac Newton published the Principia in 1687, his laws of motion solved numerous problems in physics; however, they also introduced a new conundrum, which was not fully grasped until centuries after Newton and which still poses a problem for cosmologists today. Essentially, Newton's laws work about twice as well as they are intended: they describe the everyday world that people move through, but they also account perfectly well for a world in which people walk backwards, clocks tick from evening to morning, and ______",
