    "skill": "Inferences",
    "difficulty": "Hard",
    "difficultyStatus": "provisional",
    "passage": "Exactly how Mars was formed approximately 4.5 billion years ago is a mystery, although there are several theories. One idea is that the planet was created via a titanic collision of rocks in space, spawning an all-encompassing magma ocean. When it cooled, a crust with high levels of basalt was formed. Another possibility is that parts of the first crust on Mars had a different origin, one that would primarily show large concentrations of silica. Planetary geochemist Valerie Payré and her partners analyzed data for the planet's southern hemisphere, the planet's oldest region. They discovered nine locations rich in feldspar, a mineral associated with lava flows that are higher in silica than basalt. This finding led them to conclude that ______",
    "question": "Which choice most logically completes the text?",
    "options": [
      "A. portions of Mars' surface were never covered by a crust.",
      "B. the magma ocean formed from rocks colliding in space was not all-encompassing.",
      "C. the southern hemisphere of Mars contained more silica than was previously believed.",
      "D. the first crust on Mars did not develop until long after the planet was formed."
    ],
    "answer": "B",
    "explanation": "This is a complicated question, so we're going to break it down into parts. Notice that the process outlined here requires you to work backwards through the passage. First, what is the finding? That nine regions of Mars were rich in feldspar, which is associated with lava flows that are higher in silica than basalt. What is the significance of this finding? It supports the theory that parts of the first crust on Mars had a different origin. A different origin from what? From the all-encompassing magma ocean that was created from rocks colliding in space. Logically, if parts of the crust were formed from something other than the magma ocean, then the ocean could not have been all-encompassing (covering everything). And that is what (B) says. (A) is incorrect because the passage only discusses the origins of the first crust that did exist on Mars-there is nothing to suggest that there were places without a crust. (C) is incorrect because the passage indicates only that feldspar, which is found in Mars's southern hemisphere, is higher in silica than basalt. The passage does not indicate how much silica researchers previously believed was present. (D) does not work either because the passage only mentions that Mars was formed around 4.5 billion years ago and the southern hemisphere is Mars' s oldest region - there is no mention of when the crust formed, and the amount of feldspar and silica in that area is not discussed in relation to any particular timeline.",
