    "id": "04c49e9a",
    "skill": "Command of Evidence — Textual",
    "difficulty": "Easy",
    "difficultyStatus": "provisional",
    "passage": "“Left-digit” bias, in which people focus on the first digit of a number and ignore the last, is a well-documented phenomenon that explains why prices tend to end in “9”. According to a recent study by researchers in California and Sweden, it also influences journalists' coverage of unemployment rates. Even when jobless levels and the amount of change in unemployment rates are similar in two regions, crossing a round number informs reporters' assessment of the story's newsworthiness—even when both figures fall within the same margin of error.",
    "question": "Which finding, if true, would most directly support the researchers' finding?",
    "options": [
      "A. The Bureau of Labor Statistics publishes a report of unemployment rates by state, rounding its statistics to the nearest decimal place.",
      "B. The mention of high unemployment figures in a newspaper caused consumer spending to drop by almost 2.5% in one city.",
      "C. A city newspaper ran several stories about joblessness when the unemployment rate reached 5% but quickly stopped coverage of the issue.",
      "D. A newspaper published significantly fewer stories about local unemployment when the jobless rate was 3.9% than when it rose to 4.1%."
    ],
    "answer": "D",
    "explanation": "If you scan the passage, you'll find the word researchers in the second sentence. The rest of the passage is essentially dedicated to describing what they found: \"left-digit\" bias affects whether journalists cover unemployment rates, and employment figures that cross a round number (a number ending in zero) attract more attention than ones that do not. The correct answer must therefore provide an example of a situation in which coverage of a jobless rate increased when it crossed a round number. The only answer that meets this requirement is (D): the change from 3.9% to 4.1 % unemployment was very small, but the jump over a round number correlated with greater coverage of the issue. (A) is completely off-topic, and (B) does not fit because the passage does not even mention consumer spending. (C) describes an increase in unemployment coverage when the jobless rate reached a round number (5%), but the last part of the answer (\"quickly stopped coverage\") does not fit. There is also no comparison to the amount of coverage unemployment received when the rate was below 5%, making this a weaker answer than (D).",
    "strategy": "Support Check",
    "source": {
      "book": "The Critical Reader, Fifth Edition",
      "questionPage": 139,
      "keyPage": 143,
      "ref": "critical_reader_p139_q01"
    },
    "origin": "book-ugsg",
