    "skill": "Command of Evidence — Textual",
    "difficulty": "Hard",
    "difficultyStatus": "provisional",
    "passage": "New research suggests that coffee could have a positive effect on cardiovascular health. Although caffeine is coffee's most well-known constituent, the beverage contains more than 100 biologically active components. In a study led by Jiyoung Kim, researchers at Seoul National University concluded that non-caffeinated compounds likely play a role in the positive relationship between coffee consumption and health.",
    "question": "Which finding, if true, would most directly support the researchers' conclusion?",
    "options": [
      "A. Whereas regular coffee contains from 70-140 mg of caffeine per cup, decaf contains approximately 0-7mg",
      "B. Decaffeinated coffee causes cells to produce NQO1, an enzyme that has neuroprotective benefits.",
      "C. Extracts from caffeinated coffee have been shown to aid weight loss more than a placebo.",
      "D. People who drink several cups of coffee every day are less vulnerable to certain diseases."
    ],
    "answer": "B",
    "explanation": "What is the researchers' conclusion? That non-caffeinated compounds likely play a role in the positive relationship between coffee consumption and health. The correct answer must therefore be consistent with the idea that something other than caffeine is responsible for coffee's health benefits. (A) has no relationship to this argument; the fact that decaf contains trace amounts of caffeine is irrelevant. (C) is incorrect because it focuses on the health benefits of caffeinated rather than decaffeinated coffee, and (D) does not quite work because it does not indicate what type of coffee is involved. It supports the idea that coffee has health benefits, but not the idea that something other than caffeine is responsible for them. Only (B) works: if decaf causes the production of an enzyme with \"neuroprotective benefits\" (i.e., that protects the brain), then caffeine is presumably not the cause.",
    "strategy": "Support Check",
