    "skill": "Command of Evidence — Textual",
    "difficulty": "Easy",
    "difficultyStatus": "provisional",
    "passage": "It was only when Alma Thomas turned away from figurative art and toward abstraction that she rose to acclaim as an artist. When the solidity of her line gave way to broken, vibrant colors, the beauty she had long seen emerged.",
    "question": "Which choice, if true, would most effectively support the writer's claim?",
    "options": [
      "A. Her painting Starry Night and the Astronauts (1972) includes a small kaleidoscope of red, orange, and yellow that suggests the spaceship Apollo 10.",
      "B. Thomas was fascinated by the natural world, incorporating everything from the flowers in her garden to the stars in the night sky into her paintings.",
      "C. Her Still Life with Vases and Flowers (1964), which contains realistic images, feels labored, whereas Lunar Surface (1970) glows with rich splashes of purple and blue.",
      "D. Although Thomas's own works focused on nature, she believed that art could also evoke the energy of airplanes, cars, skyscrapers, and electric signals."
    ],
    "answer": "C",
    "explanation": "What is the writer's claim? That the beauty of Alma Thomas's work emerged when she moved away from figurative art and began to work abstractly. The correct answer must support or illustrate that idea. (A) mentions Thomas's use of color but does not indicate whether this painting was figurative or abstract. (B) is off-topic, focusing on the subject matter of Thomas' s work rather than its style. (D) is incorrect for the same reason. Only (C) offers an explicit contrast between Thomas' s \"labored\" early figurative work and \"glow[ing]\" abstract later work.",
    "strategy": "Support Check",
