    "id": "002cf820",
    "image": "assets/coeq_002cf820.png",
    "skill": "Command of Evidence — Quantitative",
    "difficulty": "Medium",
    "difficultyStatus": "provisional",
    "passage": "A student studying the presence of white-nose syndrome, a disease that has decimated bat populations across North America since 2007, examined data about the number of bats in a protected area. Because bats live in the dark and their cries are inaudible to people, biologists must use acoustic detectors to record their sounds and then analyze them to identify the species present in a given location. Observing that the highest number of cries came from big brown bats (Eptesicus fuscus), the student concluded that brown bat species were not affected by the disease. [Graph: Bat Cries by Species—average cries per night: Eastern Red Bat 7; Hoary Bat 3.5; Indiana Bat 2; Tri-Colored Bat 5; Big Brown Bat 10; Little Brown Bat 2.5.]",
    "question": "Which statement best describes data from the graph that would undermine the student's conclusion?",
    "options": [
      "A. No bat species emitted more than 10 cries on average per night.",
      "B. The number of cries from little brown bats was among the lowest of any species.",
      "C. More cries were recorded for tri-colored bats than for hoary bats.",
      "D. Eastern red bats were more vocally active than big brown bats."
    ],
    "answer": "B",
    "explanation": "Although it may look complicated, this question is actually quite straightforward. What is the student's conclusion? That brown bat species were not affected by [white-nose syndrome] because the highest average number of cries recorded came from big brown bats. If you look at the graph, you can see that there are actually two brown bat species listed, and the number of cries for the other species (little brown bat) is at the very low end - a finding that would imply some brown bats are in fact affected. That is what (B) says, so it is correct. All of the other answers are off-topic.",
    "strategy": "Data-to-Claim Match",
