    "image": "assets/coeq_fc7da36a.png",
    "skill": "Command of Evidence — Quantitative",
    "difficulty": "Hard",
    "difficultyStatus": "provisional",
    "passage": "Seals are among the few mammals other than humans that are capable of learning new types of vocalizations. Whereas it is well established that adult harbor seals can acquire new vocal patterns, until recently this phenomenon had never been studied in pups. In 2021, researchers at the Max Planck Institute for Psycholinguistics and a group of colleagues conducted a study in which they played a series of pre-recorded sounds for a group of harbor seal pups ranging from one to three weeks old. They found that the baby seals were able to modify their vocalization patterns: overall, the pups lowered the fundamental frequency (F0) of their calls in response to increased noise. In some cases, the response with highly pronounced, with the same animal emitting vocalizations at much lower frequencies in high noise than in low noise. [Graph: Average Fundamental Frequency of Seal Pup Calls (Hz), showing no-noise, low-noise, and high-noise values for Seals A-F. Approximate no/low/high values: A 450/420/315; B 350/335/310; C 350/370/270; D 360/350/310; E 470/320/305; F 430/415/310.]",
    "question": "Which choice most effectively uses data from the table to support the researchers' finding?",
    "options": [
      "A. Seal B emitted vocalizations of 330 Hz in low noise and 300 Hz in high noise.",
      "B. The fundamental frequency of Seal A's vocalizations in high noise was 100 Hz lower than in low noise.",
      "C. Whereas the fundamental frequency of Seal A's call was 125 Hz lower in high noise than in no noise, the frequency of Seal B's call dropped by less than 50 Hz.",
      "D. In both low and high noise, the fundamental frequency of Seal E's call was around 150 Hz than it was without noise."
    ],
    "answer": "B",
    "explanation": "What is the researchers' finding? It appears in the last sentence: the seal pups changed their vocalizations in response to the sounds, and in some cases, the same animal might produce vocalizations with much lower fundamental frequencies in high noise than in low noise. The correct answer must therefore focus on one animal only and indicate a large gap in fundamental frequency between low and high noise. (C) makes a comparison between two seals, so it can be eliminated automatically. Be careful with (A): it does compare the frequencies in low and high noise, but the gap is fairly small (30 Hz). (D) is likewise incorrect because the correct answer must cite a large difference in the responses to the two noise levels, and here it is very similar. Only (B) offers an example of a seal whose vocalizations showed a large gap (100 Hz) between low and high noise.",
