    "passage": "The appearance of mosaic—pictures made of many small pieces—has remained unchanged for thousands of years. However, the last few decades have seen the emergence of a new ______ three-dimensional stone wall murals. One such mural was produced by Janna Morrison in 2005. She combined the piecework of mosaic murals with traditional soapstone slab carving.",
