    "passage": "Researchers have long believed that camels originated in North America, a theory that was first proposed after a camel fossil was discovered in Canada's Yukon Territory in 1913. As paleontologists eventually discovered, these camels were much larger than their modern ______ long, massive limbs and long spines on their backs, creating an enormous hump.",
