    "passage": "In 1858, Frederick Law Olmsted and Calvert Vaux won a commission to redesign Manhattan's Central Park, which at that time lacked ways for pedestrians and carriages to navigate the park without disturbing one another. ______ began work later that year.",
    "question": "Which choice completes the text so that it conforms to the conventions of Standard English?",
    "options": [
      "A. It",
      "B. He",
      "C. They",
      "D. Some"
    ],
    "answer": "C",
    "explanation": "The four choices are four different pronouns: A \"It\", B \"He\", C \"They\", D \"Some\". The sentence around them decides which one is possible. Identify what noun the pronoun is replacing (its antecedent). The pronoun must match that noun's number and clearly refer to it. It / he / she / its are singular. They / them / their are plural. Ask: \"What noun is this pronoun replacing in the action?\" Is that noun singular or plural? Match the pronoun to THAT noun's number, not the closest noun. The answer is C, \"They\".",
