    "answer": "C",
    "explanation": "The four choices are the same words. They differ only in what comes after \"prey\": A \"; including trapping it in webs; with sticky bolas they lasso it, and mimicking\", B \", including trapping it in webs, lassoing it with sticky bolas; and they mimic\", C \", including trapping it in webs; lassoing it with sticky bolas; and mimicking\", D \", including trapping it in sticky webs; to lasso it with sticky bolas, and mimicking\". A main clause needs a finite verb (one that shows tense: uses, used, will use, has used). Nonfinite forms (to use, using, having used) can function as modifiers but cannot be the main verb of a clause. Ask: \"What action does the subject perform?\" Can the verb form show tense (past / present / future)? If not, it's nonfinite — eliminate it. The answer is C, \"prey, including trapping it in webs; lassoing it with sticky bolas; and mimicking other insects\".",
