    "difficulty": "Medium",
    "difficultyStatus": "provisional",
    "passage": "Since ancient times, the fresco has served as an important method of mural making. Consisting of watercolor applied to freshy laid plaster, ______ When the plaster sets, the painting becomes an integral part of the wall.",
