    "passage": "In the winter of 1885, archaeologists in Greece discovered a unique assembly of figures. Buried in 480 BC, they had been spared 2,500 years of vandalism. Researchers were astonished—not only because of the importance of the works, but also because of the excellent preservation of ______ original surface paint.",
