    "answer": "D",
    "explanation": "Commas have four uses on the SAT: (1) before FANBOYS when joining two independent clauses, (2) after an introductory dependent clause or phrase, (3) between items in a series, and (4) around nonessential / supplementary elements. Ask: Which two things am I separating? If both are independent clauses → comma + FANBOYS. If one is a dependent clause → comma after the dependent clause. If it's extra info → pair of commas. If neither → no comma. The answer is D, \"Kennedy was a natural in front of the camera, and\".",
